=== FILE: tb/tb_crc8_block.v ===
// Self-checking constrained-random testbench for crc8_block.
// Reference model written from interface_spec.md section 2 (not from the RTL):
// the byte is folded into the running value, then eight MSB-first shifts with
// polynomial 0x07. crc = running value ^ 0xFF.
`timescale 1ns / 1ps
module tb_crc8_block;
    reg        clk   = 1'b0;
    reg        rst_n = 1'b0;
    reg        init  = 1'b0;
    reg        valid = 1'b0;
    reg  [7:0] data  = 8'h00;
    wire [7:0] crc;

    crc8_block dut (
        .clk   (clk),
        .rst_n (rst_n),
        .init  (init),
        .valid (valid),
        .data  (data),
        .crc   (crc)
    );

    always #5 clk = ~clk;

    // ---------------- reference model ----------------
    reg [7:0] model;        // running value per spec
    reg       model_known;  // defined after first reset / reload

    function [7:0] ref_take_byte;
        input [7:0] run;
        input [7:0] b;
        reg   [7:0] r;
        integer     k;
        begin
            r = run ^ b;
            for (k = 0; k < 8; k = k + 1) begin
                if (r[7])
                    r = (r << 1) ^ 8'h07;
                else
                    r = (r << 1);
            end
            ref_take_byte = r;
        end
    endfunction

    // ---------------- bookkeeping ----------------
    integer   seed;
    integer   num_cycles;
    integer   checks;
    integer   n;
    integer   roll_r, roll_i, roll_v, roll_d;
    reg       s_r, s_i, s_v;
    reg [7:0] s_d;

    reg       last_rst_n, last_init, last_valid;
    reg [7:0] last_data;

    // coverage
    integer cov_reset, cov_reset_with_valid, cov_reset_with_init;
    integer cov_init, cov_init_with_valid;
    integer cov_hold, cov_take, cov_back_to_back, cov_take_after_hold;
    integer cov_first_byte, cov_long_frame;
    integer cov_d00, cov_dff, cov_d80, cov_d01;
    integer cov_hi [0:15];
    integer frame_len;
    reg     prev_take;
    integer b;
    integer cov_fail;

    task report_mismatch;
        input [7:0]  expected;
        input [31:0] kind;   // 0: after edge, 1: between edges, 2: directed literal, 3: empty-after-reload
        begin
            $display("TB ERROR: first mismatch at time %0t (check #%0d, kind %0d): inputs at last edge rst_n=%b init=%b valid=%b data=0x%02h; model running value 0x%02h; expected crc 0x%02h, DUT crc 0x%02h (seed %0d)",
                     $time, checks, kind, last_rst_n, last_init, last_valid, last_data,
                     model, expected, crc, seed);
            $display("TEST FAILED");
            $fatal(1, "crc8_block testbench FAILED");
        end
    endtask

    task expect_literal;
        input [7:0] exp;
        begin
            checks = checks + 1;
            if (crc !== exp)
                report_mismatch(exp, 2);
        end
    endtask

    task drive_cycle;
        input       r;
        input       i;
        input       v;
        input [7:0] d;
        begin
            @(negedge clk);
            // crc must still reflect the running value between edges
            if (model_known) begin
                checks = checks + 1;
                if (crc !== (model ^ 8'hFF))
                    report_mismatch(model ^ 8'hFF, 1);
            end
            rst_n = r; init = i; valid = v; data = d;
            last_rst_n = r; last_init = i; last_valid = v; last_data = d;

            @(posedge clk);
            // reference model update, spec section 2
            if (!r) begin
                model = 8'hFF; model_known = 1'b1;         // CRC-RESET
            end else if (i) begin
                model = 8'hFF; model_known = 1'b1;         // CRC-INIT
            end else if (v) begin
                model = ref_take_byte(model, d);           // CRC-POLY / CRC-ORDER
            end                                            // else CRC-HOLD

            // coverage
            if (!r) begin
                cov_reset = cov_reset + 1;
                if (v) cov_reset_with_valid = cov_reset_with_valid + 1;
                if (i) cov_reset_with_init  = cov_reset_with_init + 1;
            end else if (i) begin
                cov_init = cov_init + 1;
                if (v) cov_init_with_valid = cov_init_with_valid + 1;
            end
            if (!r || i) begin
                if (frame_len >= 20) cov_long_frame = cov_long_frame + 1;
                frame_len = 0;
                prev_take = 1'b0;
            end else if (v) begin
                cov_take = cov_take + 1;
                if (frame_len == 0) cov_first_byte = cov_first_byte + 1;
                if (prev_take) cov_back_to_back = cov_back_to_back + 1;
                else           cov_take_after_hold = cov_take_after_hold + 1;
                frame_len = frame_len + 1;
                if (d == 8'h00) cov_d00 = cov_d00 + 1;
                if (d == 8'hFF) cov_dff = cov_dff + 1;
                if (d == 8'h80) cov_d80 = cov_d80 + 1;
                if (d == 8'h01) cov_d01 = cov_d01 + 1;
                cov_hi[d[7:4]] = cov_hi[d[7:4]] + 1;
                prev_take = 1'b1;
            end else begin
                cov_hold = cov_hold + 1;
                prev_take = 1'b0;
            end

            #1;
            if (model_known) begin
                checks = checks + 1;
                if (crc !== (model ^ 8'hFF))
                    report_mismatch(model ^ 8'hFF, 0);   // CRC-FINAL
                if ((!r || i) && (crc !== 8'h00))
                    report_mismatch(8'h00, 3);           // CRC-EMPTY
            end
        end
    endtask

    // watchdog
    initial begin
        #10000000;
        $display("TEST FAILED");
        $fatal(1, "crc8_block testbench watchdog timeout");
    end

    initial begin
        if (!$value$plusargs("seed=%d", seed))
            seed = 32'h1234_5678;
        if (!$value$plusargs("cycles=%d", num_cycles))
            num_cycles = 4000;

        model = 8'h00; model_known = 1'b0; checks = 0;
        last_rst_n = 1'b0; last_init = 1'b0; last_valid = 1'b0; last_data = 8'h00;
        cov_reset = 0; cov_reset_with_valid = 0; cov_reset_with_init = 0;
        cov_init = 0; cov_init_with_valid = 0;
        cov_hold = 0; cov_take = 0; cov_back_to_back = 0; cov_take_after_hold = 0;
        cov_first_byte = 0; cov_long_frame = 0;
        cov_d00 = 0; cov_dff = 0; cov_d80 = 0; cov_d01 = 0;
        for (b = 0; b < 16; b = b + 1) cov_hi[b] = 0;
        frame_len = 0; prev_take = 1'b0;

        $display("tb_crc8_block: seed=%0d cycles=%0d", seed, num_cycles);

        // ---------------- directed phase ----------------
        drive_cycle(1'b0, 1'b0, 1'b0, 8'h00);
        drive_cycle(1'b0, 1'b0, 1'b1, 8'hA5);   // reset wins over a byte
        drive_cycle(1'b0, 1'b1, 1'b1, 8'h3C);
        expect_literal(8'h00);                  // CRC-EMPTY after reset
        drive_cycle(1'b1, 1'b0, 1'b0, 8'h77);   // hold
        expect_literal(8'h00);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h00);
        expect_literal(8'h0C);                  // FF start, byte 00
        drive_cycle(1'b1, 1'b0, 1'b0, 8'hFF);   // hold, data ignored
        expect_literal(8'h0C);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h00);
        expect_literal(8'h28);                  // 00,00 frame accumulates
        drive_cycle(1'b1, 1'b1, 1'b0, 8'h00);   // reload
        expect_literal(8'h00);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'hFF);
        expect_literal(8'hFF);
        drive_cycle(1'b1, 1'b1, 1'b1, 8'h5A);   // init beats byte at same edge
        expect_literal(8'h00);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h80);
        expect_literal(8'h85);                  // MSB first
        drive_cycle(1'b1, 1'b1, 1'b0, 8'h00);
        drive_cycle(1'b1, 1'b0, 1'b1, 8'h01);
        expect_literal(8'h0B);                  // distinguishes bit order
        drive_cycle(1'b0, 1'b0, 1'b1, 8'h12);   // reset mid-frame, byte offered
        expect_literal(8'h00);

        // ---------------- constrained-random phase ----------------
        for (n = 0; n < num_cycles; n = n + 1) begin
            roll_r = {$random(seed)} % 1000;
            roll_i = {$random(seed)} % 1000;
            roll_v = {$random(seed)} % 1000;
            roll_d = {$random(seed)} % 1000;
            s_r = (roll_r < 10) ? 1'b0 : 1'b1;              // ~1% reset
            s_i = (roll_i < 40) ? 1'b1 : 1'b0;              // ~4% reload
            if (s_i) s_v = (roll_v < 500) ? 1'b1 : 1'b0;    // collision 50%
            else     s_v = (roll_v < 750) ? 1'b1 : 1'b0;    // 75% bytes
            if      (roll_d < 100) s_d = 8'h00;
            else if (roll_d < 200) s_d = 8'hFF;
            else if (roll_d < 250) s_d = 8'h80;
            else if (roll_d < 300) s_d = 8'h01;
            else                   s_d = $random(seed);
            drive_cycle(s_r, s_i, s_v, s_d);
        end
        // close the last frame
        drive_cycle(1'b1, 1'b1, 1'b0, 8'h00);

        // ---------------- coverage closure ----------------
        cov_fail = 0;
        if (cov_reset            < 10)  begin cov_fail = 1; $display("COVERAGE MISS: reset cycles %0d < 10", cov_reset); end
        if (cov_reset_with_valid < 5)   begin cov_fail = 1; $display("COVERAGE MISS: reset with valid %0d < 5", cov_reset_with_valid); end
        if (cov_init             < 40)  begin cov_fail = 1; $display("COVERAGE MISS: init %0d < 40", cov_init); end
        if (cov_init_with_valid  < 20)  begin cov_fail = 1; $display("COVERAGE MISS: init with valid %0d < 20", cov_init_with_valid); end
        if (cov_hold             < 200) begin cov_fail = 1; $display("COVERAGE MISS: hold %0d < 200", cov_hold); end
        if (cov_take             < 1500) begin cov_fail = 1; $display("COVERAGE MISS: bytes taken %0d < 1500", cov_take); end
        if (cov_back_to_back     < 500) begin cov_fail = 1; $display("COVERAGE MISS: back-to-back bytes %0d < 500", cov_back_to_back); end
        if (cov_take_after_hold  < 100) begin cov_fail = 1; $display("COVERAGE MISS: byte after hold %0d < 100", cov_take_after_hold); end
        if (cov_first_byte       < 40)  begin cov_fail = 1; $display("COVERAGE MISS: first byte of frame %0d < 40", cov_first_byte); end
        if (cov_long_frame       < 5)   begin cov_fail = 1; $display("COVERAGE MISS: frames >= 20 bytes %0d < 5", cov_long_frame); end
        if (cov_d00              < 50)  begin cov_fail = 1; $display("COVERAGE MISS: data 0x00 %0d < 50", cov_d00); end
        if (cov_dff              < 50)  begin cov_fail = 1; $display("COVERAGE MISS: data 0xFF %0d < 50", cov_dff); end
        if (cov_d80              < 25)  begin cov_fail = 1; $display("COVERAGE MISS: data 0x80 %0d < 25", cov_d80); end
        if (cov_d01              < 25)  begin cov_fail = 1; $display("COVERAGE MISS: data 0x01 %0d < 25", cov_d01); end
        for (b = 0; b < 16; b = b + 1)
            if (cov_hi[b] < 10) begin cov_fail = 1; $display("COVERAGE MISS: data high nibble %0h seen %0d < 10", b, cov_hi[b]); end

        $display("tb_crc8_block: %0d checks; reset=%0d init=%0d init+valid=%0d hold=%0d take=%0d long_frames=%0d",
                 checks, cov_reset, cov_init, cov_init_with_valid, cov_hold, cov_take, cov_long_frame);

        if (cov_fail) begin
            $display("TEST FAILED");
            $fatal(1, "crc8_block testbench: coverage goals not met");
        end
        $display("TEST PASSED");
        $finish;
    end
endmodule
=== END FILE ===
